import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFD', s.lower())
    out = []
    for ch in s:
        if unicodedata.category(ch).startswith('M'):
            continue
        if ch.isalnum():
            out.append(ch)
        else:
            if not out or out[-1] != '-':
                out.append('-')
    return ''.join(out).strip('-')
